# Design-only lattice Lambda_C = {s in Z^22 : 7 | sum s, (Y-J)^T s = 0 mod 3}, form G'(s,t) = (s.t - S'T')/3, S' = sum(s)/7
# (= 1/7 of the induced norm of the integer -4-eigenvector of A carried by the coclique side).
# Prediction from gluing inside K = Z^99 ∩ E_{-4}(A): disc(Lambda_C)_3 = (Z/3)^21 + Z/9 when rank_3 Q = 21.
import sys, glob, os, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from prank_test import int_kernel, rank_mod
def col_basis(V):
    # Z-basis of the lattice generated by the columns of V (list of column vectors)
    n = len(V[0]); C = [list(c) for c in V]; start = 0
    for row in range(n):
        while True:
            nz = [j for j in range(start, len(C)) if C[j][row] != 0]
            if len(nz) <= 1: break
            j0 = min(nz, key=lambda j: abs(C[j][row]))
            for j in nz:
                if j != j0:
                    q = C[j][row] // C[j0][row]; C[j] = [a - q * b for a, b in zip(C[j], C[j0])]
        nz = [j for j in range(start, len(C)) if C[j][row] != 0]
        if nz:
            C[start], C[nz[0]] = C[nz[0]], C[start]; start += 1
    return C[:start]
def smith_pparts(G, p):
    # exponents of p in the elementary divisors of integer matrix G (via ranks mod p^e, small e)
    from fractions import Fraction
    n = len(G); out = []
    # rank over Z/p^e is not a field; use local Smith via repeated elimination over Z_(p)
    M = [row[:] for row in G]; divs = []
    rows, cols = n, n; r = 0
    import math
    while True:
        best = None
        for i in range(r, rows):
            for j in range(r, cols):
                if M[i][j]:
                    v = 0; x = M[i][j]
                    while x % p == 0: x //= p; v += 1
                    if best is None or v < best[0]: best = (v, i, j)
        if best is None: break
        v, i, j = best
        M[r], M[i] = M[i], M[r]
        for row in M: row[r], row[j] = row[j], row[r]
        piv = M[r][r]
        for i2 in range(r + 1, rows):
            if M[i2][r]:
                g = math.gcd(piv, M[i2][r]); a, b = piv // g, M[i2][r] // g
                M[i2] = [a * x - b * y for x, y in zip(M[i2], M[r])]   # scales row i2 by a (a coprime to p up to p^v? a = piv/g)
        for j2 in range(r + 1, cols):
            if M[r][j2]:
                g = math.gcd(piv, M[r][j2]); a, b = piv // g, M[r][j2] // g
                for row in M: row[j2] = a * row[j2] - b * row[r]
        divs.append(v); r += 1
        # keep numbers small: remove common p'-content of each row/col is unsafe; reduce mod p^20
        P = p ** 20
        M = [[x % P for x in row] for row in M]
    return divs
def load(fn):
    t = open(fn).read().split(); v, b = int(t[0]), int(t[1]); a = list(map(int, t[2:2 + v * b]))
    return [a[i * b:(i + 1) * b] for i in range(v)]
res = collections.Counter()
files = sorted(glob.glob(os.path.join(sys.argv[1], '*.inst')))
if len(sys.argv) > 2: files = files[:int(sys.argv[2])]
for fn in files:
    Y = load(fn); v, b = 22, 77
    # generators: 21 e_i, and solutions of congruences: kernel of [1^T | -7 | 0 ; (Y-J)^T | 0 | -3 I]
    M = [[1] * v + [-7] + [0] * b] + [[Y[i][j] - 1 for i in range(v)] + [0] + [-3 * (jj == j) for jj in range(b)] for j in range(b)]
    ker = int_kernel(M)
    gens = [k[:v] for k in ker] + [[21 * (i == j) for i in range(v)] for j in range(v)]
    B = col_basis(gens); assert len(B) == 22
    def G(s, t):
        S, T = sum(s), sum(t); assert S % 7 == 0 and T % 7 == 0
        x = sum(a * c for a, c in zip(s, t)) - (S // 7) * (T // 7); assert x % 3 == 0; return x // 3
    Gm = [[G(s, t) for t in B] for s in B]
    d3 = sorted(e for e in smith_pparts(Gm, 3) if e); d7 = sorted(e for e in smith_pparts(Gm, 7) if e)
    res[(tuple(d3), tuple(d7))] += 1
for k, n in res.items(): print("3-adic exps", k[0], " 7-adic exps", k[1], " count", n)
